const points = $json.result.points;

const context = points.map((point, index) => {
    const p = point.payload;

    return `
[DOCUMENTO ${index + 1}]

Artigo: ${p.article ?? ""}
Epígrafe: ${p.article_title ?? ""}
Página inicial: ${p.page_start ?? ""}
Página final: ${p.page_end ?? ""}
Score: ${point.score.toFixed(4)}

${p.text ?? ""}
`.trim();

}).join("\n\n--------------------\n\n");

const sources = points.map(point => ({
    article: point.payload.article,
    article_title: point.payload.article_title,
    page_start: point.payload.page_start,
    page_end: point.payload.page_end,
    score: point.score
}));

return [{
    json: {
        question: $('Chat Trigger').item.json.chatInput,
        context: context,
        sources: sources
    }
}];

