parameters.jsCode:
const answer = $json.message.content;

const sources = $('Build Context').item.json.sources;

const references = sources
    .slice(0, 5)
    .map((source, index) => {

        let page;

        if (
            source.page_start &&
            source.page_end &&
            source.page_start !== source.page_end
        ) {
            page = `${source.page_start}-${source.page_end}`;
        } else {
            page = source.page_start ?? "";
        }

        return `${index + 1}. Artigo ${source.article} — ${source.article_title} (p. ${page})`;
    })
    .join("\n");

return [{
    json: {
        output: `${answer}

Fontes consultadas:
${references}`
    }
}];
